export const toScoredSearchResultFromSemantic = ({
  uid,
  title,
  type,
  nodeTypeLabel,
  score,
  resultsByUid,
}: {
  uid: string;
  title: string;
  type?: string;
  nodeTypeLabel?: string;
  score: number;
  resultsByUid: Map<string, SearchResult>;
}): ScoredSearchResult => {
  const indexedResult = resultsByUid.get(uid);
  if (indexedResult) {
    return { result: indexedResult, score, source: "semantic" };
  }

  return {
    result: {
      uid,
      title,
      type: type || "",
      nodeTypeLabel: nodeTypeLabel || "",
      excerpt: "",
      createdAt: "",
      lastModified: "",
      authorName: "Unknown",
    },
    score,
    source: "semantic",
  };
};

export type SortField = "relevance" | "alphabetical" | "dateCreated" | "author";
export type SortDirection = "asc" | "desc";

export type SortConfig = {
  field: SortField;
  direction: SortDirection;
};

export const DEFAULT_SORT_CONFIG: SortConfig = {
  field: "relevance",
  direction: "desc",
};

export const SORT_FIELD_LABELS: Record<SortField, string> = {
  relevance: "Relevance",
  alphabetical: "Alphabetical",
  dateCreated: "Date created",

export const isNonDefaultSort = (sort: SortConfig): boolean =>
  sort.field !== DEFAULT_SORT_CONFIG.field ||
  sort.direction !== DEFAULT_SORT_CONFIG.direction;

export const sortSearchResults = ({
  scoredResults,
  sort,
}: {
  scoredResults: ScoredSearchResult[];
  sort: SortConfig;
}): SearchResult[] => {
  // Semantic and MiniSearch results already arrive in their provider's relevance
  // order, so relevance sorting only has to reverse it for ascending.
  if (sort.field === "relevance") {
    const ordered =
      sort.direction === "asc" ? [...scoredResults].reverse() : scoredResults;
    return ordered.map((entry) => entry.result);
  }

  const sorted = [...scoredResults];

  sorted.sort((aEntry, bEntry) => {
    const a = aEntry.result;
    const b = bEntry.result;
    let comparison = 0;

    switch (sort.field) {
      case "alphabetical":
        comparison = compareStrings(
          getSortableTitle(a),
          getSortableTitle(b),
          sort.direction,
        );
        break;
      case "dateCreated":
        comparison = compareNumbers(
          getCreatedTime(a),
          getCreatedTime(b),
          sort.direction,
        );
        break;
      case "author": {
        const aAuthor = a.authorName.trim();
        const bAuthor = b.authorName.trim();
        if (!aAuthor && !bAuthor) comparison = 0;
        else if (!aAuthor) comparison = 1;
        else if (!bAuthor) comparison = -1;
        else comparison = compareStrings(aAuthor, bAuthor, sort.direction);
        break;
      }
    }

    return comparison || a.uid.localeCompare(b.uid);
  });

  return sorted.map((entry) => entry.result);
};

